def section(k,title,desc):return html.Div([html.Span(k,className='section-kicker'),html.H2(title),html.P(desc,className='lead')],className='section-heading')
def stat(value,label,detail=''):return html.Div([html.Span(label,className='stat-label'),html.Strong(value),html.Small(detail)],className='stat-tile')
def chart(fig):
 fig.update_layout(template='plotly_white',font=dict(family='Arial',color='#263e49',size=12),paper_bgcolor='rgba(0,0,0,0)',plot_bgcolor='rgba(0,0,0,0)',margin=dict(l=45,r=25,t=30,b=65),colorway=COLORS,legend=dict(orientation='h',y=-.2),hoverlabel=dict(bgcolor='white'),height=350)
 return dcc.Graph(figure=fig,config={'displaylogo':False,'responsive':True},className='science-chart')
def box(title,content,caption=None):return html.Section([html.H3(title),content,html.P(caption,className='chart-caption') if caption else None],className='viz-card')
def detail(title,content):return html.Details([html.Summary(title),html.Div(content,className='detail-body')],className='evidence-detail')
def data(root):
 p=root/'resultados_analizados/cierre_11'
 return pd.read_csv(p/'resumen_experimento.csv'),json.loads((p/'analisis_reserva.json').read_text()),pd.read_csv(p/'metricas_reserva_por_semilla.csv')
def comparison(root,interval=False):
 df,a,_=data(root);fig=go.Figure()
 if interval:
  for i,(k,v) in enumerate(a['modelos'].items()):
   mean=v['macro_f1_reserva_media'];fig.add_trace(go.Scatter(x=[mean],y=[NAMES[k]],mode='markers',marker=dict(size=14,color=COLORS[i]),error_x=dict(type='data',symmetric=False,array=[v['IC95_pacientes_sup']-mean],arrayminus=[mean-v['IC95_pacientes_inf']],thickness=3),name=NAMES[k],showlegend=False,hovertemplate='%{y}: %{x:.3f}<extra></extra>'))
  fig.update_xaxes(range=[0,1],title='Macro-F1 de reserva · IC 95% por pacientes')
 else:
  for col,name,color in [('macro_f1_val_media','Validación','#becbd8'),('macro_f1_reserva_media','Reserva','#087e83')]:fig.add_trace(go.Bar(x=[NAMES[x] for x in df.modelo],y=df[col],name=name,marker_color=color,text=[f'{x:.3f}' for x in df[col]],textposition='outside',hovertemplate='%{x}<br>'+name+': %{y:.4f}<extra></extra>'))
  fig.update_layout(barmode='group');fig.update_yaxes(range=[0,1],title='Macro-F1 medio')
 return chart(fig)
