 return html.Section([html.Div([html.Div('NUCLS / DEEP LEARNING',className='hero-kicker'),html.H1(['De la morfología nuclear',html.Br(),html.Em('a la evidencia experimental.')]),html.P('Tres modelos base. Una evaluación por paciente. Un recorrido desde la literatura y la calidad de los datos hasta la generalización.',className='hero-copy'),html.Div([html.Span('Entregable 1'),html.Span('Andrés Duarte Chaves'),html.Span('08 NOV 2026')],className='hero-meta')],className='hero-text'),html.Div([html.Div([html.Figure([html.Img(src='/galeria/'+x['archivo'],alt='Ejemplo anotado de entrenamiento: '+label),html.Figcaption(label)]) for x,label in zip(examples,['Tumoral','Linfocito','Estromal'])],className='hero-micrographs'),html.P('H&E · RGB 128 × 128 · ejemplos de entrenamiento',className='micrograph-caption'),html.Div([html.Span('DISEÑO EXPERIMENTAL'),html.Strong('33 corridas'),html.Small('11 semillas × 3 modelos · inicialización desde cero')],className='hero-experiment')],className='hero-visual')],className='research-hero')
