def overview(root,legacy):
 return [section('01 / PANORAMA','Lo que muestran los experimentos','ResNet50 obtuvo el mayor macro-F1 medio en validación y fue el modelo seleccionado antes de evaluar la reserva.'),html.Div([box('De validación a reserva',comparison(root),'Mismas tres clases y protocolo local. Las barras muestran medias de 11 semillas, sin intervalos.'),html.Div([html.Span('HALLAZGO PRINCIPAL',className='section-kicker'),html.H3('El reto está en la generalización.'),html.P('El macro-F1 de ResNet50 pasa de 0,793 en validación a 0,638 en reserva. El resultado favorece descriptivamente al modelo, pero seis pacientes limitan el alcance de la conclusión.'),html.Div([html.Strong('0,302'),html.Span('F1 estromal medio en reserva')],className='finding-number'),html.P('La clase estromal sigue siendo la más difícil. Su soporte es de 70 recortes; 42 pertenecen a un solo paciente.')],className='insight-panel')],className='two-columns'),html.Div([box('Literatura que justifica el diseño',html.P('1.330 registros cribados; 21 informes focales dentro de 166 lecturas documentadas. Se separan clasificadores de recortes y sistemas de detección/segmentación.')),box('EDA que examina la muestra',html.P('Balance, retención, integridad, similitud y desplazamiento. Partición de desarrollo: 83 pacientes de entrenamiento y 21 de validación.')),box('Implementación contrastable',html.P('CNN compacta con BN, DenseNet121 y ResNet50. Entrada RGB común, 11 semillas por modelo y análisis exploratorio por paciente.'))],className='three-columns'),html.Div([html.B('Alcance del cierre'),html.Span('13 informes no recuperados · 11 de las 22 semillas previstas por modelo · concordancia, Grad-CAM y latencia pendientes.')],className='scope-strip'),detail('Pregunta de investigación, población y antecedentes del piloto',legacy)]
def models(root,legacy):
 df,a,seeds=data(root)
 matrix=[[v['f1_media'] for v in a['modelos'][k]['clases']] for k in NAMES]
 heat=go.Figure(go.Heatmap(z=matrix,x=['Tumoral · n=769','Linfocito · n=130','Estromal · n=70'],y=list(NAMES.values()),zmin=0,zmax=1,colorscale=[[0,'#f4ede3'],[.5,'#87c5c2'],[1,'#00616a']],text=[[f'{x:.3f}' for x in row] for row in matrix],texttemplate='%{text}',hovertemplate='%{y}<br>%{x}<br>F1 medio: %{z:.4f}<extra></extra>',colorbar=dict(title='F1')))
 return [section('04 / MODELOS','Comparación bajo un protocolo común','Once semillas por modelo. Inicialización desde cero; selección mediante validación. La reserva no se usa para ajustar hiperparámetros.'),html.Div([box(NAMES[k],html.Div([html.Span(sub,className='model-family'),html.P(text),html.Strong(f"{a['modelos'][k]['macro_f1_reserva_media']:.3f}",className='model-score'),html.Small('macro-F1 medio de reserva')])) for k,sub,text in [('softmaxcnn_bn','CNN COMPACTA','Referencia de menor capacidad, BatchNorm y adaptación de pooling para ventanas nativas de 128×128.'),('densenet121','CONEXIONES DENSAS','Reutilización de características mediante conexiones entre capas. Clasificador final de tres clases.'),('resnet50','CONEXIONES RESIDUALES','Bloques residuales de 50 capas. Seleccionado por su macro-F1 de validación; no por la reserva.')]],className='three-columns model-cards'),html.Div([box('Cambio de desempeño',comparison(root)),box('Incertidumbre entre pacientes',comparison(root,True),'Bootstrap agrupado: 46.656 remuestras de seis pacientes, ajustes fijos. IC exploratorios; no equivalen a IC entre semillas.')],className='two-columns'),html.Div([box('El promedio no cuenta toda la historia',chart(heat),'F1 por clase promediado entre las 11 semillas. Soportes de la reserva, no pacientes independientes.'),box('Variación entre inicializaciones',html.Div([html.Label('Métrica de reserva',htmlFor='metric-choice'),dcc.Dropdown(id='metric-choice',options=[{'label':l,'value':v} for l,v in [('Macro-F1','macro_f1'),('Exactitud balanceada','exactitud_balanceada'),('AUC macro OvR','AUC_macro_OvR'),('Error de calibración ECE','ECE_10_bins')]],value='macro_f1',clearable=False),html.Div(id='seed-chart')]),'Cada punto corresponde a una semilla sobre la misma reserva. ECE menor es mejor; no mide discriminación.')],className='two-columns'),detail('Tablas completas, calibración, matrices de confusión y método estadístico',legacy)]
def seed_figure(root,metric):
 _,_,df=data(root);fig=go.Figure()
 for i,k in enumerate(NAMES):
  d=df[df.modelo==k];fig.add_trace(go.Box(y=d[metric],name=NAMES[k],boxpoints='all',jitter=.25,pointpos=0,marker_color=COLORS[i],customdata=d.semilla,hovertemplate='Semilla %{customdata}<br>Valor: %{y:.4f}<extra>%{fullData.name}</extra>'))
 fig.update_layout(showlegend=False);fig.update_yaxes(title=metric)
 return chart(fig)
def literature(root,legacy):
 d=pd.read_csv(root/'evidencias/literatura/adjudicacion_sintesis_20261108.csv').fillna('');counts=d.grupo_sintesis.value_counts();fig=go.Figure(go.Bar(x=counts.values,y=[GROUPS[k] for k in counts.index],orientation='h',marker_color=['#087e83','#9bafc5','#ba8250','#bbd6d5','#c87665'],text=counts.values,textposition='outside'));fig.update_layout(showlegend=False);fig.update_yaxes(automargin=True)
 records=[{'id':r.id,'titulo':r.titulo,'grupo':GROUPS[r.grupo_sintesis],'doi':r.doi,'motivo':r.motivo_individual,'limitacion':r.limitaciones} for r in d.itertuples()]
 return [section('02 / ESTADO DEL ARTE','De la búsqueda a la comparación crítica','La evidencia se organiza por tarea, representación y protocolo. F1 de detección, PQ de segmentación y macro-F1 de recortes no se tratan como métricas equivalentes.'),html.Div([stat('1.717','Registros identificados','Scopus · WoS · IEEE'),stat('1.330','Registros cribados','Después de depuración inicial'),stat('21','Informes focales','No 21 estudios independientes'),stat('13','No recuperados','Barreras registradas al corte')],className='stats-row'),html.Div([box('Capas de la síntesis',chart(fig),'166 informes con lectura dirigida documentada. Una fuente con alerta editorial se trata por separado.'),box('Cómo se traduce en el experimento',html.Div([html.H4('Comparar arquitecturas exactas'),html.P('ResNet50 y DenseNet121 se distinguen de encoders modificados, ensambles y modelos que reciben máscaras.'),html.H4('Conservar la unidad de evaluación'),html.P('NuCLS V2 separa pacientes y procedencia. No se equiparan sus resultados con particiones aleatorias de recortes.'),html.H4('Documentar el límite'),html.P('Revisión crítica asistida por IA, sin segundo revisor independiente; cobertura incompleta.')]))],className='two-columns'),box('Explorador de los 166 informes',html.Div([html.P('Filtra por título, DOI o grupo desde cada columna; ordena los resultados y consulta el motivo de cada decisión.'),dash_table.DataTable(id='evidence-table',data=records,columns=[{'name':l,'id':k} for l,k in [('ID','id'),('Informe','titulo'),('Capa','grupo'),('DOI','doi'),('Decisión y fundamento','motivo'),('Limitaciones','limitacion')]],filter_action='native',sort_action='native',page_size=8,style_table={'overflowX':'auto'},style_cell={'whiteSpace':'normal','height':'auto','minWidth':'110px','maxWidth':'300px','textAlign':'left','padding':'14px','fontFamily':'Arial','fontSize':'12px','lineHeight':'1.5','border':'1px solid #e3e9ec'},style_header={'backgroundColor':'#edf4f4','fontWeight':'bold'},style_data_conditional=[{'if':{'row_index':'odd'},'backgroundColor':'#f8fafb'}])])),detail('Flujo PRISMA, comparadores exactos y síntesis bibliográfica completa',legacy)]
def eda(root,legacy):
 fig=go.Figure()
 for label,vals,col in [('Entrenamiento',[47.99,30.67,21.34],'#087e83'),('Validación',[54.08,29.13,16.79],'#ba8250')]:fig.add_trace(go.Bar(name=label,x=['Tumoral','Linfocito','Estromal'],y=vals,marker_color=col,text=[f'{v:.2f}%' for v in vals],textposition='outside'))
 fig.update_yaxes(range=[0,65],title='Porcentaje de recortes');fig.update_layout(barmode='group')
 return [section('03 / ANÁLISIS EXPLORATORIO','La muestra condiciona el resultado','El EDA de píxeles se restringe al desarrollo. Las imágenes de reserva no intervienen en las decisiones de preparación.'),html.Div([stat('14.539','Entrenamiento','83 pacientes'),stat('2.049','Validación','21 pacientes'),stat('128 × 128','Entrada RGB','Ventanas interiores elegibles'),stat('29,79 M','Pares dHash comparados','Sin candidatos con distancia ≤4')],className='stats-row'),html.Div([box('Composición de clases en desarrollo',chart(fig),'Porcentajes redondeados de la partición V2. La composición cambia aunque las clases sean las mismas.'),html.Div([html.Span('DESPLAZAMIENTO',className='section-kicker'),html.H3('¿Se distingue la procedencia?'),html.Div([html.Strong('0,677'),html.Span('Exactitud balanceada · train vs. validación')],className='finding-number'),html.P('IC 95% por pacientes: 0,558–0,785. Los descriptores distinguen parcialmente las particiones; no identifican una causa ni prueban que la CNN utilice un atajo.'),html.P('Integridad RGB y dimensiones verificadas. Los casos atípicos se priorizan para revisión; no se eliminan automáticamente.')],className='insight-panel')],className='two-columns'),detail('Abrir EDA completo: retención, píxeles, incertidumbre y piloto histórico',legacy)]
def render(tab,root,legacy):
 if tab=='contexto':return overview(root,legacy)
 if tab=='modelos':return models(root,legacy)
 if tab=='literatura':return literature(root,legacy)
 if tab=='eda':return eda(root,legacy)
 if tab=='imagenes':return [section('05 / ATLAS VISUAL','La representación que recibe el modelo','Ejemplos reales de entrenamiento. Las etiquetas corresponden al núcleo objetivo, no a todo el campo.')]+legacy
 if tab=='discusion':return [section('06 / DISCUSIÓN','Qué sostiene la evidencia y qué falta','Los resultados describen esta partición y este protocolo. La reserva pequeña limita las conclusiones sobre generalización.')]+legacy
 return [section('07 / REPRODUCIBILIDAD','Del resultado a su evidencia','Documentación, código, cuadernos ejecutados y limitaciones del cierre académico.'),html.Div([box('Protocolo V2',html.P('33 corridas · 11 semillas por modelo. El plan original contemplaba 22; se conserva la enmienda del cierre.')),box('Cuadernos ejecutados',html.A('Abrir EDA con salidas ↗',href='https://aduartech81.github.io/NuCLS_DeepLearning/10_eda_v2.html')),box('Código y trazabilidad',html.A('Consultar repositorio ↗',href='https://github.com/aduartech81/NuCLS_DeepLearning'))],className='three-columns'),detail('Metodología completa y recursos de reproducción',legacy)]
